<script setup lang="ts">
import { askConfirm } from '@/utils/confirmDialog';
import OptionSelect from '@/Components/UI/OptionSelect.vue';
import { ADDENDUM_REASONS, NOTE_TYPES, PARTNER_AGENCIES, SERVICE_TYPES, VISIT_LOCATIONS, isCpuReferral } from '@/utils/caseOptions';
import ReferralTracker from '@/Components/Referrals/ReferralTracker.vue';
import ReferralStatusForm from '@/Components/Referrals/ReferralStatusForm.vue';
import { followUp, stepLabel, type ReferralTargets, type TrackedReferral } from '@/utils/referralTracking';
import { referralTone } from '@/utils/caseDisplay';
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue';
import { Link, useForm, usePage } from '@inertiajs/vue3';
import FormField from '@/Components/UI/FormField.vue';
import StatusBadge from '@/Components/UI/StatusBadge.vue';
import { ClipboardList, HandHeart, NotebookPen, Plus, Send, Sparkles, X } from '@lucide/vue';
import { registerUnsavedCaseWork } from '@/Security/browserHistory';
import { calendarDateLabel, manilaDateTime, manilaInputToUtc, philippineTimestamp } from '@/utils/philippineTime';
import type { MonitoringVisit, ProgressNote } from '@/types/monitoring';
import type { CaseTask } from '@/types/casework';
import type { PageProps } from '@/types';
type NoteReferral=TrackedReferral&{case_note_id?:number|null;referred_to?:string|null;purpose?:string|null;target_date?:string|null};
type ServiceItem={id:number;service_type:string;specific_detail:string|null;amount:string|number|null;date_provided:string;provided_by:string|null;referral_id:number|null;case_note_id:number|null;recorded_by_name?:string|null};
const props=withDefaults(defineProps<{caseId:number;active:boolean;visits:MonitoringVisit[];notes:ProgressNote[];tasks:CaseTask[];referrals?:NoteReferral[];services?:ServiceItem[];referralTargets?:ReferralTargets;referralTransitions?:Record<string,string[]>;startWith?:'notes'|'visits';clientNames?:string[]}>(),{clientNames:()=>[],referrals:()=>[],services:()=>[],referralTargets:()=>({response_days:5,completion_days:30}),referralTransitions:()=>({}),startWith:'notes'});
const page=usePage<PageProps>();const canNote=computed(()=>page.props.auth.permissions.includes('cases.note'));const canVisit=computed(()=>page.props.auth.permissions.includes('activities.manage'));const canOffline=computed(()=>page.props.auth.permissions.includes('offline.use'));
const view=ref<'visits'|'notes'>(props.startWith);const message=ref('');const failures=ref<string[]>([]);const errorSummary=ref<HTMLElement|null>(null);
const visit=useForm({visited_at:manilaDateTime().slice(0,10),observations:'',location:'',risks:'',next_steps:''});
const today=manilaDateTime().slice(0,10);
const note=useForm({note_type:'contact',note_type_other:'',occurred_at:manilaDateTime(),body:'',action_taken:'',next_steps:'',create_follow_up:false,follow_up_title:'',follow_up_due_at:'',
 service:{service_type:'',specific_detail:'',amount:'' as string|number,date_provided:today,provided_by:'',referral_id:'' as number|''}});
/** Referrals are conducted from the Intervention Plan (Kalinga forms); referral notes still show in this history. */

const noteTypes=NOTE_TYPES.filter(type=>type.value!=='referral');const isService=computed(()=>note.note_type==='service_delivery');
const serviceType=computed(()=>SERVICE_TYPES.find(item=>item.value===note.service.service_type));
const NOTE_PROMPTS:Record<string,string>={contact:'Who was met, where, and what was observed or discussed.',monitoring:'Progress on the care plan goals and the child\'s current situation.',referral:'Background and reason for the referral; only what the receiving office needs.',service_delivery:'What was given or done, and how the child or family responded.',coordination:'Who was coordinated with and what was agreed.',case_review:'Points reviewed and decisions made.',other:'Factual record of the activity.'};
const referralsByNote=computed(()=>{const map=new Map<number,NoteReferral[]>();for(const item of props.referrals){if(item.case_note_id)map.set(item.case_note_id,[...(map.get(item.case_note_id)??[]),item]);}return map;});
const servicesByNote=computed(()=>{const map=new Map<number,ServiceItem[]>();for(const item of props.services){if(item.case_note_id)map.set(item.case_note_id,[...(map.get(item.case_note_id)??[]),item]);}return map;});
const tracking=ref<number|null>(null);
const peso=(value:string|number|null)=>value===null||value===''?'':new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP',maximumFractionDigits:2}).format(Number(value));
const openReferrals=computed(()=>props.referrals.filter(item=>['DRAFT','PENDING','SENT','ACCEPTED','IN_PROGRESS'].includes(item.status)));
const overdueReferrals=computed(()=>openReferrals.value.filter(item=>followUp(item,props.referralTargets)?.overdue));
const assistanceTotal=computed(()=>props.services.reduce((sum,item)=>sum+Number(item.amount||0),0));
/** Privacy nudge: the child's name typed into a narrative travels with every copy of the note. */
const nameInNote=computed(()=>{const text=`${note.body} ${note.action_taken} ${note.next_steps}`.toLowerCase();return props.clientNames.filter(name=>name&&name.length>2).some(name=>new RegExp(`\\b${name.toLowerCase().replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}\\b`).test(text));});
const noteReferralLabel=(noteId:number)=>{const refs=referralsByNote.value.get(noteId)??[];return refs.length&&refs.every(ref=>!isCpuReferral(ref))?'Referral to external agency':refs.length?'Referral to CPU member':'Referral';};
const referralLabel=(item:NoteReferral)=>[item.referred_to,item.purpose||item.service_category].filter(Boolean).join(' - ');
const addendum=useForm({body:'',addendum_reason:'',occurred_at:manilaDateTime()});const addendumFor=ref<number|null>(null);const addendumEditor=ref<HTMLElement|null>(null);
const busy=computed(()=>visit.processing||note.processing||addendum.processing);const dirty=computed(()=>visit.isDirty||note.isDirty||addendum.isDirty);
const visitLimit=ref(10);const noteLimit=ref(10);const visibleVisits=computed(()=>props.visits.slice(0,visitLimit.value));const visibleNotes=computed(()=>props.notes.slice(0,noteLimit.value));
const human=(value:string)=>value.replaceAll('_',' ');
// Entry forms open on demand so the record history leads the tab. A form with unsaved entries stays open.
const showVisitForm=ref(false);const showNoteForm=ref(false);
function openEntry(){if(view.value==='visits')showVisitForm.value=true;else showNoteForm.value=true;nextTick(()=>document.getElementById(view.value==='visits'?'monitor-visit-date':'monitor-note-type')?.focus());}
async function closeVisitForm(){if(visit.isDirty&&!(await askConfirm({title:'Discard this unfinished visit record?',confirmLabel:'Discard',tone:'danger'})))return;visit.reset();showVisitForm.value=false;}
async function closeNoteForm(){if(note.isDirty&&!(await askConfirm({title:'Discard this unfinished progress note?',confirmLabel:'Discard',tone:'danger'})))return;note.reset();showNoteForm.value=false;}
const linkedTasks=(id:number)=>props.tasks.filter(task=>task.source_type==='case_note'&&Number(task.source_id)===id);
async function failed(errors:Record<string,string>){failures.value=Object.values(errors).filter(Boolean);await nextTick();errorSummary.value?.focus();}
function begin(){if(busy.value)return false;failures.value=[];message.value='';return true;}
function recordVisit(){if(!begin())return;visit.post(route('cases.monitoring.store',props.caseId),{preserveScroll:true,onError:failed,onSuccess:()=>{visit.reset('observations','location','risks','next_steps');visit.defaults();showVisitForm.value=false;message.value='Monitoring visit recorded.';}});}
function finalizeNote(){if(!begin())return;note.transform(data=>{const {service,...rest}=data;return {...rest,occurred_at:manilaInputToUtc(data.occurred_at),follow_up_due_at:manilaInputToUtc(data.follow_up_due_at),...(data.note_type==='service_delivery'?{service:{...service,amount:serviceType.value?.amount?service.amount:null,referral_id:service.referral_id||null}}:{})};}).post(route('cases.notes.store',props.caseId),{preserveScroll:true,onError:failed,onSuccess:()=>{const kind=note.note_type;note.reset('body','action_taken','next_steps','follow_up_title','follow_up_due_at','service','note_type_other');note.create_follow_up=false;note.defaults();showNoteForm.value=false;message.value=kind==='service_delivery'?'Service recorded in Services provided.':'Progress note finalized. The original record is preserved.';}});}
async function chooseAddendum(id:number){
 if(busy.value)return;
 if(addendumFor.value!==null&&addendumFor.value!==id&&addendum.isDirty){await failed({body:'Save or cancel the current addendum before choosing another original note.'});return;}
 addendumFor.value=id;await nextTick();addendumEditor.value?.scrollIntoView({block:'start'});addendumEditor.value?.focus({preventScroll:true});
}
async function cancelAddendum(){if(busy.value)return;if(addendum.isDirty&&!(await askConfirm({title:'Discard this unfinished addendum?',confirmLabel:'Discard',tone:'danger'})))return;addendum.reset();addendumFor.value=null;}
function finalizeAddendum(){if(addendumFor.value===null||!begin())return;const source=addendumFor.value;addendum.transform(data=>({...data,occurred_at:manilaInputToUtc(data.occurred_at)})).post(route('cases.notes.addendum',[props.caseId,source]),{preserveScroll:true,onError:failed,onSuccess:()=>{addendum.reset();addendumFor.value=null;message.value='Progress-note addendum finalized. The original remains unchanged.';}});}
function compose(kind:'service_delivery'){view.value='notes';if(!note.isDirty)note.note_type=kind;openEntry();}
defineExpose({compose});
const emit=defineEmits<{refer:[]}>();
const remove=registerUnsavedCaseWork(()=>dirty.value||busy.value);onBeforeUnmount(remove);
watch(()=>props.active,visible=>{if(!visible||busy.value)return;if(!note.isDirty){note.occurred_at=manilaDateTime();note.defaults();}if(!visit.isDirty){visit.visited_at=manilaDateTime().slice(0,10);visit.defaults();}});
</script>
<template>
 <div class="space-y-4">
  <header class="flex flex-wrap items-start justify-between gap-3"><div class="min-w-0"><h2 class="ui-section-title text-lg">Progress notes & monitoring</h2><p class="ui-muted mt-1 max-w-3xl">Write progress notes, refer the child to a CPU member or agency, and record services given, all in one timeline. Visit records stay in their own tab.</p></div><div class="flex flex-wrap gap-2"><Link v-if="canOffline" :href="route('offline.workspace')" class="ui-button min-h-10 text-sm">Field mode</Link><button v-if="view==='notes'&&canNote" type="button" class="ui-button min-h-10 gap-1.5 text-sm" @click="emit('refer')"><Send class="h-4 w-4" aria-hidden="true"/>Refer (Intervention Plan)</button><button v-if="view==='notes'&&canNote" type="button" class="ui-button min-h-10 gap-1.5 text-sm" @click="note.note_type='service_delivery';openEntry()"><HandHeart class="h-4 w-4" aria-hidden="true"/>Record service</button><button v-if="view==='visits'?canVisit:canNote" type="button" class="ui-button ui-button-primary min-h-10 gap-1.5 text-sm" :aria-expanded="view==='visits'?showVisitForm:showNoteForm" @click="openEntry"><Plus class="h-4 w-4" aria-hidden="true"/>{{view==='visits'?'Add visit':'Add progress note'}}</button></div></header>
  <dl class="grid grid-cols-2 gap-2 sm:grid-cols-4" aria-label="Progress summary"><div class="rounded-xl border border-[var(--color-line)] bg-white px-3 py-2"><dt class="text-xs text-slate-600">Progress notes</dt><dd class="text-lg font-semibold text-slate-900">{{notes.length}}</dd></div><div class="rounded-xl border border-[var(--color-line)] bg-white px-3 py-2"><dt class="text-xs text-slate-600">Open referrals</dt><dd class="text-lg font-semibold text-slate-900">{{openReferrals.length}}<span v-if="overdueReferrals.length" class="ml-1 text-xs font-semibold text-rose-700">{{overdueReferrals.length}} overdue</span></dd></div><div class="rounded-xl border border-emerald-200 bg-emerald-50/60 px-3 py-2"><dt class="text-xs text-emerald-900">Services provided</dt><dd class="text-lg font-semibold text-emerald-900">{{services.length}}</dd></div><div class="rounded-xl border border-emerald-200 bg-emerald-50/60 px-3 py-2"><dt class="text-xs text-emerald-900">Assistance given</dt><dd class="text-lg font-semibold text-emerald-900">{{peso(assistanceTotal)||'PHP 0'}}</dd></div></dl>
  <div v-if="failures.length" ref="errorSummary" role="alert" tabindex="-1" class="rounded-md border border-rose-300 bg-rose-50 p-4 text-sm text-rose-900"><p class="font-semibold">Review the fields below. Your entries remain on this page.</p><ul class="mt-2 list-inside list-disc"><li v-for="(failure,index) in failures" :key="index">{{failure}}</li></ul></div>
  <p v-if="message" role="status" class="rounded-md border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-900">{{message}}</p><p v-if="busy" role="status" class="text-sm text-slate-600">Recording your casework...</p>
  <p v-if="dirty" class="rounded-md border border-amber-300 bg-kalinga-warm p-3 text-sm text-amber-950">Unfinished entries are retained on this page. Save online before closing. You can cancel navigation to keep working.</p>
  <nav aria-label="Monitoring record types" class="ui-tabs"><button type="button" class="ui-tab" :class="view==='notes'?'ui-tab-active':''" :aria-current="view==='notes'?'page':undefined" @click="view='notes'"><NotebookPen class="h-4 w-4" aria-hidden="true"/>Progress notes ({{notes.length}})</button><button type="button" class="ui-tab" :class="view==='visits'?'ui-tab-active':''" :aria-current="view==='visits'?'page':undefined" @click="view='visits'"><ClipboardList class="h-4 w-4" aria-hidden="true"/>Visit records ({{visits.length}})</button></nav>
  <section v-if="view==='visits'" aria-label="Monitoring visits" class="space-y-4">
   <form v-if="canVisit" v-show="showVisitForm||visit.isDirty" aria-labelledby="visit-entry-title" autocomplete="off" class="rounded-xl border border-brand-200 bg-brand-50/40 p-4 sm:p-5" @submit.prevent="recordVisit"><div class="flex items-start justify-between gap-3"><div><h3 id="visit-entry-title" class="ui-section-title">Visit record</h3><p class="ui-muted mt-1">Record only operationally necessary observations and location details.</p></div><button type="button" class="grid h-10 w-10 shrink-0 place-items-center rounded-lg hover:bg-white" aria-label="Close visit record" :disabled="busy" @click="closeVisitForm"><X class="h-4 w-4" aria-hidden="true"/></button></div><fieldset :disabled="busy" class="mt-4 grid gap-4 md:grid-cols-2"><legend class="sr-only">Visit record fields</legend>
    <FormField id="monitor-visit-date" label="Visit date" :error="visit.errors.visited_at" required><input id="monitor-visit-date" v-model="visit.visited_at" type="date" required class="ui-field" :aria-invalid="Boolean(visit.errors.visited_at)||undefined"></FormField>
    <FormField id="monitor-location" label="Location (optional)" :error="visit.errors.location"><OptionSelect id="monitor-location" v-model="visit.location" :options="VISIT_LOCATIONS" /></FormField>
    <div class="md:col-span-2"><FormField id="monitor-observations" label="Observations" :error="visit.errors.observations" required><textarea id="monitor-observations" v-model="visit.observations" required maxlength="5000" rows="4" class="ui-field" :aria-invalid="Boolean(visit.errors.observations)||undefined"/></FormField></div>
    <FormField id="monitor-risks" label="Risks observed" :error="visit.errors.risks"><textarea id="monitor-risks" v-model="visit.risks" maxlength="5000" rows="3" class="ui-field"/></FormField>
    <FormField id="monitor-next-steps" label="Next steps" :error="visit.errors.next_steps"><textarea id="monitor-next-steps" v-model="visit.next_steps" maxlength="5000" rows="3" class="ui-field"/></FormField><div class="flex gap-2 md:col-span-2"><button class="ui-button-primary" type="submit">Record visit</button><button type="button" class="ui-button" @click="closeVisitForm">Cancel</button></div>
   </fieldset></form>
   <div class="overflow-hidden rounded-xl border border-[var(--color-line)]"><div class="flex items-center justify-between gap-3 border-b border-[var(--color-line)] bg-[#faf9fd] px-4 py-3"><h3 class="ui-section-title">Visit history</h3><span class="text-xs text-slate-600">{{visibleVisits.length}} of {{visits.length}}</span></div>
    <table v-if="visits.length" class="ui-table ui-table-stack"><thead><tr><th scope="col" class="w-32">Date</th><th scope="col">Findings / observations</th><th scope="col">Risks observed</th><th scope="col">Next steps</th><th scope="col">Location</th></tr></thead><tbody><tr v-for="item in visibleVisits" :key="item.id" class="align-top"><td data-label="Date" class="whitespace-nowrap font-medium text-slate-800">{{calendarDateLabel(item.visited_at)}}</td><td data-label="Findings" class="max-w-sm"><p class="whitespace-pre-wrap break-words">{{item.observations}}</p></td><td data-label="Risks" class="max-w-xs"><p v-if="item.risks" class="whitespace-pre-wrap break-words text-amber-900">{{item.risks}}</p><span v-else class="text-slate-500">-</span></td><td data-label="Next steps" class="max-w-xs"><p v-if="item.next_steps" class="whitespace-pre-wrap break-words">{{item.next_steps}}</p><span v-else class="text-slate-500">-</span></td><td data-label="Location" class="break-words">{{item.location||'-'}}</td></tr></tbody></table>
    <p v-if="!visits.length" class="ui-muted p-4">No visits recorded.</p><button v-if="visibleVisits.length<visits.length" type="button" class="ui-button m-4" @click="visitLimit+=10">Show more visits</button></div>
  </section>
  <section v-else aria-label="Professional progress notes" class="space-y-4">
   <form v-if="canNote" v-show="showNoteForm||note.isDirty" aria-labelledby="note-entry-title" autocomplete="off" class="rounded-xl border border-brand-200 bg-brand-50/40 p-4 sm:p-5" @submit.prevent="finalizeNote"><div class="flex items-start justify-between gap-3"><div><h3 id="note-entry-title" class="ui-section-title">{{isService?'Record a service provided':'Finalize progress note'}}</h3><p class="ui-muted mt-1">The original remains unchanged after finalization. Corrections or supplementary information require an addendum.</p></div><button type="button" class="grid h-10 w-10 shrink-0 place-items-center rounded-lg hover:bg-white" aria-label="Close progress note" :disabled="busy" @click="closeNoteForm"><X class="h-4 w-4" aria-hidden="true"/></button></div><fieldset :disabled="busy" class="mt-4 space-y-4"><legend class="sr-only">Progress note fields</legend><div class="grid gap-4 sm:grid-cols-2">
    <FormField id="monitor-note-type" label="Record type" :error="note.errors.note_type"><select id="monitor-note-type" v-model="note.note_type" class="ui-field"><option v-for="type in noteTypes" :key="type.value" :value="type.value">{{type.label}}</option></select></FormField>
    <FormField v-if="note.note_type==='other'" id="monitor-note-type-other" label="Specify the record type" :error="note.errors.note_type_other" required hint="For example: school visit, barangay meeting, phone call with the partner."><input id="monitor-note-type-other" v-model="note.note_type_other" maxlength="120" required class="ui-field"></FormField>
    <FormField id="monitor-note-time" label="When it occurred (Philippine time)" :error="note.errors.occurred_at" required><input id="monitor-note-time" v-model="note.occurred_at" type="datetime-local" required class="ui-field"></FormField></div>
    <div v-if="isService" class="space-y-3 rounded-xl border border-emerald-200 bg-emerald-50/70 p-4"><p class="flex items-center gap-1.5 text-sm font-semibold text-emerald-950"><HandHeart class="h-4 w-4" aria-hidden="true"/>Service provided</p><div class="grid gap-3 sm:grid-cols-2">
     <FormField id="note-svc-type" label="Service type" :error="note.errors['service.service_type']" required><select id="note-svc-type" v-model="note.service.service_type" required class="ui-field"><option value="">Select service</option><option v-for="type in SERVICE_TYPES" :key="type.value" :value="type.value">{{type.label}}</option></select></FormField>
     <FormField id="note-svc-date" label="Date provided" :error="note.errors['service.date_provided']" required><input id="note-svc-date" v-model="note.service.date_provided" type="date" :max="today" required class="ui-field"></FormField>
     <FormField v-if="note.service.service_type" id="note-svc-detail" :label="note.service.service_type==='Other'?'Specify the service':'Specific service'" :error="note.errors['service.specific_detail']" :required="note.service.service_type==='Other'"><input id="note-svc-detail" v-model="note.service.specific_detail" maxlength="255" class="ui-field" :required="note.service.service_type==='Other'" :placeholder="serviceType?.detail"></FormField>
     <FormField v-if="serviceType?.amount" id="note-svc-amount" :label="note.service.service_type==='Financial'?'Amount (PHP)':'Amount (PHP, optional)'" :error="note.errors['service.amount']" :required="note.service.service_type==='Financial'"><input id="note-svc-amount" v-model="note.service.amount" type="number" min="0" step="0.01" inputmode="decimal" :required="note.service.service_type==='Financial'" class="ui-field"></FormField>
     <FormField id="note-svc-by" label="Provided by" :error="note.errors['service.provided_by']"><OptionSelect id="note-svc-by" v-model="note.service.provided_by" :options="PARTNER_AGENCIES" /></FormField>
     <FormField v-if="referrals.length" id="note-svc-ref" label="Result of a referral (optional)" :error="note.errors['service.referral_id']"><select id="note-svc-ref" v-model="note.service.referral_id" class="ui-field"><option value="">Not from a referral</option><option v-for="item in referrals" :key="item.id" :value="item.id">{{referralLabel(item)}}</option></select></FormField></div></div>
    <p v-if="nameInNote" class="rounded-md border border-amber-300 bg-amber-50 p-3 text-xs text-amber-950">The child's name appears in this note. Consider using the alias or case number instead, so the name does not spread in reports and referrals.</p>
    <FormField id="monitor-note-body" :label="'Professional record'" :error="note.errors.body" required><textarea id="monitor-note-body" v-model="note.body" maxlength="5000" rows="5" required class="ui-field" :placeholder="NOTE_PROMPTS[note.note_type]"/></FormField>
    <div class="grid gap-4 sm:grid-cols-2"><FormField id="monitor-note-action" label="Action taken (optional)" :error="note.errors.action_taken"><textarea id="monitor-note-action" v-model="note.action_taken" maxlength="3000" rows="3" class="ui-field" placeholder="What was done during this contact"/></FormField><FormField id="monitor-note-next" label="Next steps (optional)" :error="note.errors.next_steps"><textarea id="monitor-note-next" v-model="note.next_steps" maxlength="3000" rows="3" class="ui-field" placeholder="Planned follow-up actions"/></FormField></div>
    <label class="flex min-h-11 items-center gap-3 text-sm text-slate-800"><input v-model="note.create_follow_up" type="checkbox" class="h-5 w-5 rounded border-slate-400">Create a linked follow-up task</label>
    <div v-if="note.create_follow_up" class="space-y-3 rounded-md border border-sky-200 bg-sky-50 p-3"><p class="text-xs leading-5 text-sky-950">A task is added to your work list only when you select this option and finalize the note.</p><FormField id="monitor-follow-title" label="Follow-up task title" :error="note.errors.follow_up_title" required><input id="monitor-follow-title" v-model="note.follow_up_title" maxlength="255" required class="ui-field"></FormField><FormField id="monitor-follow-due" label="Follow-up target (Philippine time)" :error="note.errors.follow_up_due_at"><input id="monitor-follow-due" v-model="note.follow_up_due_at" type="datetime-local" class="ui-field"></FormField></div><div class="flex gap-2"><button type="submit" class="ui-button-primary">{{isService?'Save note and record service':'Finalize progress note'}}</button><button type="button" class="ui-button" @click="closeNoteForm">Cancel</button></div>
   </fieldset></form>
   <form v-if="canNote&&addendumFor!==null" ref="addendumEditor" tabindex="-1" aria-labelledby="monitor-addendum-title" autocomplete="off" class="scroll-mt-24 rounded-xl border border-amber-300 bg-kalinga-warm p-4" @submit.prevent="finalizeAddendum"><div class="flex flex-wrap items-center justify-between gap-2"><h3 id="monitor-addendum-title" class="text-base font-semibold text-amber-950">Addendum to progress note #{{addendumFor}}</h3><button type="button" class="ui-button" :disabled="busy" @click="cancelAddendum">Cancel addendum</button></div><p class="mt-2 text-sm leading-6 text-amber-950">This adds a linked record. The selected original note remains unchanged.</p><fieldset :disabled="busy" class="mt-4 space-y-4"><legend class="sr-only">Progress-note addendum fields</legend><FormField id="monitor-addendum-reason" label="Reason for addendum" :error="addendum.errors.addendum_reason" required><OptionSelect id="monitor-addendum-reason" v-model="addendum.addendum_reason" :options="ADDENDUM_REASONS" required /></FormField><FormField id="monitor-addendum-time" label="Addendum occurrence (Philippine time)" :error="addendum.errors.occurred_at" required><input id="monitor-addendum-time" v-model="addendum.occurred_at" type="datetime-local" required class="ui-field"></FormField><FormField id="monitor-addendum-body" label="Supplementary professional record" :error="addendum.errors.body" required><textarea id="monitor-addendum-body" v-model="addendum.body" maxlength="5000" rows="4" required class="ui-field"/></FormField><button type="submit" class="ui-button-primary">Finalize addendum</button></fieldset></form>
   <div class="overflow-hidden rounded-xl border border-[var(--color-line)]"><div class="flex items-center justify-between gap-3 border-b border-[var(--color-line)] bg-[#faf9fd] px-4 py-3"><h3 class="ui-section-title">Professional note history</h3><span class="text-xs text-slate-600">{{visibleNotes.length}} of {{notes.length}}</span></div><p class="px-4 pt-3 text-xs leading-5 text-slate-600">Occurrence and finalization are separate times. All displayed times are Philippine time.</p>
    <ol class="note-timeline px-4 pb-2 pt-3"><li v-for="item in visibleNotes" :key="item.id" class="relative pb-4 pl-6"><span aria-hidden="true" class="absolute left-0 top-1.5 h-2.5 w-2.5 rounded-full ring-4" :class="item.record_type==='addendum'?'bg-amber-500 ring-amber-100':'bg-brand-600 ring-brand-100'"/><article class="rounded-xl border border-[var(--color-line)] bg-white p-4"><div class="flex flex-wrap items-center justify-between gap-2"><div class="flex flex-wrap items-center gap-2"><StatusBadge :label="item.record_type==='addendum'?'Addendum':(item.note_type==='other'&&item.note_type_other?`Other: ${item.note_type_other}`:(item.note_type==='referral'?noteReferralLabel(item.id):NOTE_TYPES.find(type=>type.value===item.note_type)?.label??human(item.note_type||'progress note')))" :tone="item.record_type==='addendum'?'warning':item.note_type==='referral'?'info':item.note_type==='service_delivery'?'success':'brand'"/><span class="text-xs text-slate-600">{{item.author}} - occurred {{philippineTimestamp(item.occurred_at||item.created_at)}}</span></div><button v-if="canNote&&item.finalized_at&&item.record_type!=='addendum'" type="button" class="ui-button min-h-9 text-xs" :disabled="busy" @click="chooseAddendum(item.id)">Add addendum</button></div><p v-if="item.previous_note_id" class="mt-2 text-xs font-semibold text-amber-900">Supplement to note #{{item.previous_note_id}}</p><p class="mt-2 whitespace-pre-wrap break-words text-sm leading-6 text-slate-700">{{item.body}}</p><dl v-if="item.action_taken||item.next_steps" class="mt-3 grid gap-3 border-t border-slate-100 pt-3 text-sm sm:grid-cols-2"><div v-if="item.action_taken"><dt class="text-xs font-semibold text-slate-600">Action taken</dt><dd class="mt-1 whitespace-pre-wrap break-words text-slate-700">{{item.action_taken}}</dd></div><div v-if="item.next_steps"><dt class="text-xs font-semibold text-slate-600">Next steps</dt><dd class="mt-1 whitespace-pre-wrap break-words text-slate-700">{{item.next_steps}}</dd></div></dl><p v-if="item.addendum_reason" class="mt-1 text-sm text-amber-950">Reason: {{item.addendum_reason}}</p><div v-for="ref in referralsByNote.get(item.id) ?? []" :key="`r${ref.id}`" class="mt-3 rounded-lg border border-sky-200 bg-sky-50/60 p-3 text-sm"><div class="flex flex-wrap items-center justify-between gap-2"><p class="flex min-w-0 items-center gap-1.5 font-semibold text-sky-950"><Send class="h-4 w-4 shrink-0" aria-hidden="true"/><span class="break-words">Referred to {{referralLabel(ref)}}</span></p><div class="flex flex-wrap items-center gap-2"><StatusBadge :label="stepLabel(ref.status)" :tone="referralTone(ref.status)" dot/><span v-if="followUp(ref,referralTargets)" class="text-xs font-semibold" :class="followUp(ref,referralTargets)?.overdue?'text-rose-700':'text-slate-600'">{{followUp(ref,referralTargets)?.label}}</span><button type="button" class="ui-link min-h-9 text-xs" :aria-expanded="tracking===ref.id" @click="tracking=tracking===ref.id?null:ref.id">{{tracking===ref.id?'Hide tracking':'Track / update'}}</button></div></div><p class="mt-1 text-xs text-sky-900">{{ref.service_category}}<span v-if="ref.target_date"> - expected by {{calendarDateLabel(ref.target_date)}}</span></p><div v-if="tracking===ref.id" class="mt-3 rounded-lg bg-white p-3"><ReferralTracker :referral="ref" :targets="referralTargets"/><ReferralStatusForm :referral-id="ref.id" :status="ref.status" :allowed-statuses="referralTransitions[ref.status] ?? []"/></div></div><div v-for="svc in servicesByNote.get(item.id) ?? []" :key="`s${svc.id}`" class="mt-3 flex flex-wrap items-center justify-between gap-2 rounded-lg border border-emerald-200 bg-emerald-50/70 p-3 text-sm"><p class="flex min-w-0 items-center gap-1.5 font-semibold text-emerald-950"><HandHeart class="h-4 w-4 shrink-0" aria-hidden="true"/><span class="break-words">Service provided: {{svc.service_type}}<span v-if="svc.specific_detail" class="font-normal"> - {{svc.specific_detail}}</span></span></p><span class="text-xs text-emerald-900"><b v-if="svc.amount">{{peso(svc.amount)}} · </b>{{calendarDateLabel(svc.date_provided)}}<span v-if="svc.provided_by"> · {{svc.provided_by}}</span></span></div><p class="mt-2 text-xs text-slate-500"><span v-if="item.finalized_at">Finalized {{philippineTimestamp(item.finalized_at)}}</span><span v-else>Recorded {{philippineTimestamp(item.created_at)}} - finalization not recorded</span></p><div v-for="task in linkedTasks(item.id)" :key="task.id" class="mt-3 rounded-md border border-sky-200 bg-sky-50 p-3 text-sm text-sky-950"><p class="font-semibold">Linked follow-up: {{task.title}}</p><p class="mt-1">{{human(task.status)}} - target {{philippineTimestamp(task.due_at)}}</p></div></article></li></ol>
    <p v-if="!notes.length" class="ui-muted p-4">No progress notes yet.</p><button v-if="visibleNotes.length<notes.length" type="button" class="ui-button m-4" @click="noteLimit+=10">Show more notes</button></div>
  </section>
 </div>
</template>

